import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';

export const LOGO_CORETERRA_BASE64 = 'data:image/png;base64,';
export const CAP_CORETERRA_BASE64 = 'data:image/png;base64,';
export const TTD_SETYO_BASE64 = 'data:image/png;base64,';

