  invoiceNumber?: string;
  invoiceDate?: string;
  poNumber?: string;
  customerName?: string;
  projectName?: string;
  itemDescription?: string;
  itemDescriptionEn?: string;
  milestone?: string;
  unit?: string;
  amount?: number;
  totalDp?: number;
  totalContract?: number;
  prevBilledDp?: number;
