function formatMoney(val: number, currency = 'IDR') {
  if (currency === 'USD') {
    return `$ ${val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  }
  return `Rp ${val.toLocaleString('id-ID', { minimumFractionDigits: 0, maximumFractionDigits: 0 })},-`;
}

/**
 * Format invoice number to safe filename string (e.g. INV-001-004_IKPT-SOLOK-001-08-2026.pdf)
 */
function getInvoiceFilename(invNumber: string): string {
  const safeName = invNumber.trim().replace(/[/\\]/g, '-');
  return safeName.endsWith('.pdf') ? safeName : `${safeName}.pdf`;
}

/**
 * Open PDF in a new browser tab with custom preview toolbar & guaranteed filename download
 */
function openPdfInNewTab(doc: jsPDF, invNumber: string) {
  const filename = getInvoiceFilename(invNumber);
  const pdfBlob = doc.output('blob');
  
  // Create File object with explicit name to enforce filename across browsers
  const pdfFile = new File([pdfBlob], filename, { type: 'application/pdf' });
  const blobUrl = URL.createObjectURL(pdfFile);

  const newWin = window.open('', '_blank');
  if (newWin) {
    newWin.document.write(`
      <!DOCTYPE html>
      <html lang="id">
        <head>
          <meta charset="utf-8">
          <title>${filename}</title>
          <style>
            * { box-sizing: border-box; }
            html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; background: #323639; display: flex; flex-direction: column; }
            .header-bar { height: 48px; background: #1e293b; color: #ffffff; display: flex; align-items: center; justify-content: space-between; padding: 0 16px; border-bottom: 1px solid #334155; flex-shrink: 0; z-index: 99; }
            .doc-title { font-size: 14px; font-weight: 600; color: #f8fafc; display: flex; align-items: center; gap: 8px; font-mono: true; }
            .doc-title span { background: #0f172a; padding: 3px 8px; border-radius: 4px; border: 1px solid #334155; font-size: 12px; color: #fbbf24; }
            .btn-group { display: flex; align-items: center; gap: 10px; }
            .btn { text-decoration: none; display: inline-flex; align-items: center; gap: 6px; padding: 7px 14px; font-size: 13px; font-weight: 600; border-radius: 6px; cursor: pointer; border: none; transition: all 0.2s; }
            .btn-primary { background: #d97706; color: #ffffff; }
            .btn-primary:hover { background: #b45309; }
            .btn-secondary { background: #334155; color: #f1f5f9; }
            .btn-secondary:hover { background: #475569; }
            iframe { width: 100%; flex: 1; border: none; background: #525659; }
          </style>
        </head>
        <body>
          <div class="header-bar">
            <div class="doc-title">
              <span>PDF INVOICE</span> ${filename}
            </div>
            <div class="btn-group">
              <button onclick="window.frames[0].focus(); window.frames[0].print();" class="btn btn-secondary">
                🖨️ Cetak / Print
              </button>
              <a href="${blobUrl}" download="${filename}" class="btn btn-primary">
                ⬇️ Unduh PDF (${filename})
              </a>
            </div>
          </div>
          <iframe id="pdfFrame" src="${blobUrl}#filename=${encodeURIComponent(filename)}"></iframe>
        </body>
      </html>
    `);
    newWin.document.close();
  } else {
    // Fallback to direct save if popups blocked
    doc.save(filename);
  }
}

/**
 * Draw a beautiful corporate footer with perfect spacing and zero text collision
 */
function drawBeautifulFooter(doc: jsPDF, companyName = 'PT CORETERRA GEO ENGINEERING') {
  const pageWidth = doc.internal.pageSize.width; // 210mm
  const pageHeight = doc.internal.pageSize.height; // 297mm

  const footerHeight = 15;
  const footerY = pageHeight - footerHeight;

  // 1. Accent Gold/Amber Line above Footer Bar
  doc.setFillColor(217, 119, 6); // Amber 600 #D97706
  doc.rect(0, footerY - 1.2, pageWidth, 1.2, 'F');

  // 2. Main Dark Footer Bar
  doc.setFillColor(15, 23, 42); // Slate 900 #0F172A
  doc.rect(0, footerY, pageWidth, footerHeight, 'F');

  // 3. Footer Content (3 Non-Overlapping Columns)
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(255, 255, 255);
  doc.text(companyName.toUpperCase(), 14, footerY + 5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.2);
  doc.setTextColor(203, 213, 225); // Slate 300
  doc.text('Gardenia Estate, Ciputat, Tangsel • +62 812-1494-1641', 14, footerY + 9.5);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(251, 191, 36); // Amber 400 #FBBF24
  doc.text('★ THANK YOU FOR YOUR BUSINESS ★', pageWidth / 2, footerY + 5, { align: 'center' });

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.2);
  doc.setTextColor(148, 163, 184); // Slate 400
  doc.text('Dokumen Invoice Resmi • ANSA Finance System', pageWidth / 2, footerY + 9.5, { align: 'center' });

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(255, 255, 255);
  doc.text('PT CORETERRA', pageWidth - 14, footerY + 5, { align: 'right' });

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.5);
  doc.setTextColor(203, 213, 225);
  doc.text('Halaman 1 dari 1', pageWidth - 14, footerY + 9.5, { align: 'right' });
}

/**
 * Render Stamp & Signature Overlay Block (Stamp on left/behind, Signature on top/right)
 */
function renderSignatureBlock(doc: jsPDF, sigX: number, startY: number, companyName: string) {
  const primaryColor: [number, number, number] = [15, 23, 42];
  const textColor: [number, number, number] = [51, 65, 85];

  let y = startY;

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);
  doc.setTextColor(...textColor);
  doc.text('Hormat Kami / Sincerely,', sigX + 15, y, { align: 'center' });

  y += 4;
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(...primaryColor);
  doc.text(companyName, sigX + 15, y, { align: 'center' });

  // 1. Draw STAMP FIRST (Behind, on left of signature area)
  try {
    doc.addImage(CAP_CORETERRA_BASE64, 'PNG', sigX - 12, y + 1, 23, 26.27);
  } catch (e) {
    console.error('Failed to render stamp:', e);
  }

  // 2. Draw SIGNATURE SECOND (On top of stamp, extending right)
  try {
    doc.addImage(TTD_SETYO_BASE64, 'PNG', sigX - 2, y + 4, 40, 14.6);
  } catch (e) {
    console.error('Failed to render signature:', e);
  }

  y += 24;

  // Name & Title
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...primaryColor);
  doc.text('Setyo Mardani', sigX + 15, y, { align: 'center' });

  y += 3.5;
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Director / Direktur', sigX + 15, y, { align: 'center' });
}

/**
 * Download / Open exact invoice requested by user for PT Solusi Monitoring Indonesia
 * Supports dynamic customization via customParams (Item Description, Milestone, Unit, Amounts).
 */
export function generateExactCoreterraInvoicePDF(customParams?: CustomInvoiceParams) {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
  });

  // Apply custom parameters or defaults
  const invNumber = customParams?.invoiceNumber || 'INV/001/004_IKPT-SOLOK-001/08/2026';
  const invDate = customParams?.invoiceDate || '05 August 2026';
  const poNum = customParams?.poNumber || 'KONTRAK/004_IKPT-SOLOK-001/2026';
  const custName = customParams?.customerName || 'PT Solusi Monitoring Indonesia';
  const projName = customParams?.projectName || 'Washbore Borpile & Foundation Project, Muara Laboh, West Sumatera';
  const itemDesc = customParams?.itemDescription || 'First Down Payment';
  const itemDescEn = customParams?.itemDescriptionEn || '';
  const milestoneText = customParams?.milestone || 'Field preparation';
  const unitText = customParams?.unit || 'Lump Sump';
  const invAmount = customParams?.amount ?? 175000000;
  const totalDp = customParams?.totalDp ?? 800000000;
  const totalContract = customParams?.totalContract ?? 2870121121;

  const isDp = itemDesc.toLowerCase().includes('dp') ||
               itemDesc.toLowerCase().includes('uang muka') ||
               itemDesc.toLowerCase().includes('down payment');
  
  const isDp2 = invAmount === 625000000 || itemDesc.includes('Tahap 2') || itemDesc.includes('Part 2');
  const prevPaidTotal = customParams?.prevBilledTotal ?? customParams?.prevBilledDp ?? (isDp2 ? 175000000 : (isDp ? 0 : 800000000));
  const prevInvNum = customParams?.prevInvoiceNum || (isDp2 ? 'INV/001/004_IKPT-SOLOK-001/08/2026' : '');

  const cumulativeBilledTotal = prevPaidTotal + invAmount;
  const remainingDp = Math.max(0, totalDp - cumulativeBilledTotal);
  const remainingContract = Math.max(0, totalContract - cumulativeBilledTotal);
  const dpPercentage = ((totalDp / totalContract) * 100).toFixed(2);

  const pageWidth = doc.internal.pageSize.width; // 210mm
  const primaryColor: [number, number, number] = [15, 23, 42]; // Slate 900
  const accentColor: [number, number, number] = [217, 119, 6];  // Amber 600
  const textColor: [number, number, number] = [51, 65, 85];     // Slate 700
  const lightBg: [number, number, number] = [248, 250, 252];    // Slate 50

  let y = 10;

  // Header Banner Accent Line (Top)
  doc.setFillColor(...accentColor);
  doc.rect(14, y, pageWidth - 28, 1.5, 'F');
  y += 5;

  // Logo Image (Top Left: Width=38mm, Height=12.58mm)
  try {
    doc.addImage(LOGO_CORETERRA_BASE64, 'PNG', 14, y, 38, 12.58);
  } catch (e) {
    console.error('Failed to render logo:', e);
  }

  // Company Info Text (X = 54mm, ends at X = 118mm)
  const compX = 54;
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  doc.setTextColor(...primaryColor);
  doc.text('PT CORETERRA GEO ENGINEERING', compX, y + 3);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(5.8);
  doc.setTextColor(...accentColor);
  doc.text('GEOTECHNICAL • DRILLING • CIVIL ENGINEERING • MINING CONSULTANT', compX, y + 6.5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.2);
  doc.setTextColor(...textColor);
  doc.text('Gardenia Estate, Blok A5 No 12, Ciputat, Tangsel, Banten 15412', compX, y + 10);
  doc.text('Email: admin.cge@coreterra-geo.com | Contact: +62 812-1494-1641', compX, y + 13.5);

  // Invoice Header Box (Top Right: Width=60mm, X=136mm - Clear 18mm Gap!)
  const boxWidth = 60;
  const boxX = pageWidth - 14 - boxWidth; // 136mm
  
  doc.setFillColor(...lightBg);
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(boxX, y, boxWidth, 19, 2, 2, 'FD');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10.5);
  doc.setTextColor(...primaryColor);
  doc.text('INVOICE / FAKTUR', boxX + 4, y + 4.2);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.5);
  doc.setTextColor(...textColor);
  doc.text('No:', boxX + 4, y + 9.5);
  doc.setFont('helvetica', 'bold');
  doc.text(invNumber, boxX + 10, y + 9.5);

  doc.setFont('helvetica', 'normal');
  doc.text('Date / Tgl:', boxX + 4, y + 14.5);
  doc.setFont('helvetica', 'bold');
  doc.text(invDate, boxX + 18, y + 14.5);

  y += 23;

  // Thin separator
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.4);
  doc.line(14, y, pageWidth - 14, y);
  y += 5;

  // 2-Column Section: Bill From & Bill To
  const colWidth = (pageWidth - 34) / 2;

  // Bill From Box
  doc.setFillColor(...lightBg);
  doc.roundedRect(14, y, colWidth, 32, 2, 2, 'F');
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(14, y, colWidth, 32, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.setTextColor(...accentColor);
  doc.text('BILL FROM / DARI:', 18, y + 5.5);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...primaryColor);
  doc.text('PT Coreterra Geo Engineering', 18, y + 10.5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Gardenia Estate, Blok A5 No 12, Ciputat', 18, y + 15);
  doc.text('Kota Tangerang Selatan, Banten 15412', 18, y + 19);
  doc.text('Telp/WA: +62 812-1494-1641', 18, y + 23.5);
  doc.text('Email: admin.cge@coreterra-geo.com', 18, y + 27.5);

  // Bill To Box
  const billToX = 14 + colWidth + 6;
  doc.setFillColor(...lightBg);
  doc.roundedRect(billToX, y, colWidth, 32, 2, 2, 'F');
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(billToX, y, colWidth, 32, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.setTextColor(...accentColor);
  doc.text('BILL TO / KEPADA:', billToX + 4, y + 5.5);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...primaryColor);
  doc.text(custName, billToX + 4, y + 10.5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Ruko Puri Botanical, Blok I-H No. 10-11', billToX + 4, y + 15);
  doc.text('Joglo, Kembangan, Jakarta Barat 11640', billToX + 4, y + 19);
  doc.text('Attn: Procurement / Finance Department', billToX + 4, y + 23.5);
  doc.text('Email: info@solusimonitoring.id', billToX + 4, y + 27.5);

  y += 36;

  // Project Reference & Contract Overview Card
  doc.setFillColor(241, 245, 249);
  doc.roundedRect(14, y, pageWidth - 28, 22, 2, 2, 'F');
  doc.setDrawColor(203, 213, 225);
  doc.roundedRect(14, y, pageWidth - 28, 22, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8);
  doc.setTextColor(...primaryColor);
  doc.text('PROJECT & CONTRACT REFERENCE / REFERENSI PROYEK', 18, y + 5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Contract / PO No:', 18, y + 10.5);
  doc.setFont('helvetica', 'bold');
  doc.text(poNum, 44, y + 10.5);

  doc.setFont('helvetica', 'normal');
  doc.text('Project Name:', 18, y + 15.5);
  doc.setFont('helvetica', 'bold');
  doc.text(projName, 44, y + 15.5);

  // Total Contract Value Display
  const refValX = pageWidth - 16;
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Nilai Total Kontrak Proyek:', refValX - 48, y + 10.5, { align: 'left' });
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...accentColor);
  doc.text(formatMoney(totalContract), refValX, y + 16, { align: 'right' });

  y += 26;

  // Invoice Details Table (Customizable Item, Milestone, Unit, Amount)
  const fullItemDesc = `${itemDesc}${itemDescEn ? `\n(${itemDescEn})` : ''}`;

  autoTable(doc, {
    startY: y,
    head: [['No.', 'Item & Payment Terms / Description', 'Milestone', 'Unit', 'Amount (IDR)']],
    body: [
      [
        '1.',
        fullItemDesc,
        milestoneText,
        unitText,
        formatMoney(invAmount)
      ]
    ],
    theme: 'grid',
    headStyles: {
      fillColor: primaryColor,
      textColor: [255, 255, 255],
      fontStyle: 'bold',
      fontSize: 8,
      halign: 'center',
      valign: 'middle',
      cellPadding: 3,
    },
    bodyStyles: {
      textColor: [30, 41, 59],
      fontSize: 8,
      valign: 'middle',
      cellPadding: 3.5,
      lineWidth: 0.2,
      lineColor: [226, 232, 240]
    },
    columnStyles: {
      0: { cellWidth: 10, halign: 'center' },
      1: { cellWidth: 55, halign: 'left' },
      2: { cellWidth: 60, halign: 'left' },
      3: { cellWidth: 22, halign: 'center' },
      4: { cellWidth: 'auto', halign: 'right', fontStyle: 'bold' },
    },
    margin: { left: 14, right: 14 },
  });

  // @ts-ignore
  y = doc.lastAutoTable.finalY + 4;

  // Summary & Breakdown Table Box
  const sumWidth = 95;
  const sumX = pageWidth - 14 - sumWidth;

  doc.setFillColor(...lightBg);
  doc.roundedRect(sumX, y, sumWidth, 32, 2, 2, 'FD');
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(sumX, y, sumWidth, 32, 2, 2, 'S');

  const rpX = sumX + 54;
  const numRightX = sumX + sumWidth - 4;

  let sy = y + 4.5;
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Nilai Total Kontrak Proyek:', sumX + 4, sy);
  doc.text('Rp', rpX, sy);
  doc.setFont('helvetica', 'bold');
  doc.text(`${totalContract.toLocaleString('id-ID')},-`, numRightX, sy, { align: 'right' });

  sy += 4.5;
  doc.setFont('helvetica', 'normal');
  if (isDp) {
    doc.text(`Total Alokasi DP (${dpPercentage}%):`, sumX + 4, sy);
    doc.text('Rp', rpX, sy);
    doc.setFont('helvetica', 'bold');
    doc.text(`${totalDp.toLocaleString('id-ID')},-`, numRightX, sy, { align: 'right' });
  } else {
    doc.text('Total Dibayar Sebelumnya:', sumX + 4, sy);
    doc.text('Rp', rpX, sy);
    doc.setFont('helvetica', 'bold');
    doc.text(`${prevPaidTotal.toLocaleString('id-ID')},-`, numRightX, sy, { align: 'right' });
  }

  sy += 4.5;
  doc.setFont('helvetica', 'normal');
  doc.text('Tagihan Ini (Subtotal):', sumX + 4, sy);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(...primaryColor);
  doc.text('Rp', rpX, sy);
  doc.text(`${invAmount.toLocaleString('id-ID')},-`, numRightX, sy, { align: 'right' });

  sy += 4.5;
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(...textColor);
  doc.text('PPN 11% / Tax:', sumX + 4, sy);
  doc.text('Rp', rpX, sy);
  doc.text('0,- (Included)', numRightX, sy, { align: 'right' });

  sy += 5.5;
  doc.setDrawColor(203, 213, 225);
  doc.line(sumX + 4, sy - 2, sumX + sumWidth - 4, sy - 2);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.setTextColor(...accentColor);
  doc.text('Total Harus Dibayar / Due:', sumX + 4, sy + 1.5);
  doc.text('Rp', rpX, sy + 1.5);
  doc.text(`${invAmount.toLocaleString('id-ID')},-`, numRightX, sy + 1.5, { align: 'right' });

  // Left Note Box
  const noteWidth = pageWidth - 28 - sumWidth - 5; // 82mm
  const noteBoxHeight = (prevInvNum && !isDp) ? 35 : 32;
  doc.setFillColor(254, 243, 199);
  doc.roundedRect(14, y, noteWidth, noteBoxHeight, 2, 2, 'F');
  doc.setDrawColor(252, 211, 77);
  doc.roundedRect(14, y, noteWidth, noteBoxHeight, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(146, 64, 14);
  if (isDp) {
    doc.text('INFORMASI STRUKTUR DP & KONTRAK', 18, y + 4.5);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6.8);
    doc.setTextColor(120, 53, 15);
    if (prevPaidTotal > 0) {
      doc.text(`• Total Alokasi DP: ${formatMoney(totalDp)}`, 18, y + 8);
      doc.text(`• DP Tahap 1 (Lunas): ${formatMoney(prevPaidTotal)}`, 18, y + 12);
      doc.text(`• Tagihan Ini (DP Tahap 2): ${formatMoney(invAmount)}`, 18, y + 16);
      doc.text(`• Sisa DP Belum Ditagih: ${remainingDp > 0 ? formatMoney(remainingDp) : 'Rp 0,- (Lunas)'}`, 18, y + 20);
      doc.text(`• Sisa Kontrak Akhir: ${formatMoney(remainingContract)}`, 18, y + 24);
    } else {
      doc.text(`• Total Alokasi DP: ${formatMoney(totalDp)}`, 18, y + 9.5);
      doc.text(`• Tagihan Ini: ${formatMoney(invAmount)}`, 18, y + 14);
      doc.text(`• Sisa DP Belum Ditagih: ${formatMoney(remainingDp)}`, 18, y + 18.5);
      doc.text(`• Sisa Kontrak Akhir: ${formatMoney(remainingContract)}`, 18, y + 23);
    }
  } else {
    doc.text('INFORMASI STRUKTUR KONTRAK & PEMBAYARAN', 18, y + 4.5);
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(6.5);
    doc.setTextColor(120, 53, 15);
    doc.text(`• Nilai Total Kontrak: ${formatMoney(totalContract)}`, 18, y + 8);
    doc.text(`• Total Dibayar Sebelumnya: ${formatMoney(prevPaidTotal)} (Lunas)`, 18, y + 12.5);
    doc.text(`• Tagihan Ini (${itemDesc}): ${formatMoney(invAmount)}`, 18, y + 17);
    doc.text(`• Sisa Nilai Kontrak Akhir: ${formatMoney(remainingContract)}`, 18, y + 21.5);
    if (prevInvNum) {
      const refText = `• Reff Invoice Lunas: ${prevInvNum}`;
      const splitRef = doc.splitTextToSize(refText, noteWidth - 8); // Max 74mm width!
      doc.text(splitRef, 18, y + 25.5);
    }
  }

  y += 36;

  // Bank Account Details Box
  doc.setFillColor(...lightBg);
  doc.roundedRect(14, y, pageWidth - 28, 25, 2, 2, 'FD');
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(14, y, pageWidth - 28, 25, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8);
  doc.setTextColor(...accentColor);
  doc.text('REKENING PEMBAYARAN / BANK DETAILS FOR PAYMENT:', 18, y + 4.5);

  const bankInfo = [
    ['Nama Bank / Bank Name', ': Bank Mandiri'],
    ['Atas Nama / Account Name', ': PT Coreterra Geo Engineering'],
    ['Nomor Rekening / Account No.', ': 103-00-1332575-4'],
    ['Kode SWIFT / IFSC Code', ': BMRIIDJA'],
    ['Cabang / Branch Name', ': KCP Jakarta Gedung Jaya'],
    ['NPWP / TIN', ': 1000 0000 1002 1192'],
  ];

  let by1 = y + 9.5;
  let by2 = y + 9.5;
  bankInfo.forEach(([lbl, val], idx) => {
    doc.setFontSize(7.5);
    if (idx < 3) {
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(...textColor);
      doc.text(lbl, 18, by1);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(...primaryColor);
      doc.text(val, 58, by1);
      by1 += 4.5;
    } else {
      const bx = 110;
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(...textColor);
      doc.text(lbl, bx, by2);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(...primaryColor);
      doc.text(val, bx + 44, by2);
      by2 += 4.5;
    }
  });

  y += 28;

  // Signature Block & Stamp (Right aligned)
  const sigX = pageWidth - 65;
  renderSignatureBlock(doc, sigX, y, 'PT Coreterra Geo Engineering');

  // Render Beautiful Footer
  drawBeautifulFooter(doc, 'PT CORETERRA GEO ENGINEERING');

  openPdfInNewTab(doc, invNumber);
}

/**
 * Standard dynamic Billing Invoice PDF generator matching Coreterra template format
 */
export function generateBillingInvoicePDF(
  schedule: BillingSchedule,
  term: BillingTerm,
  companySettings: CompanySettings
) {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4',
  });

  const pageWidth = doc.internal.pageSize.width; // 210mm
  const currency = schedule.currency || 'IDR';

  // Colors
  const primaryColor: [number, number, number] = [15, 23, 42]; // Slate 900
  const accentColor: [number, number, number] = [217, 119, 6];  // Amber 600
  const textColor: [number, number, number] = [51, 65, 85];     // Slate 700
  const lightBg: [number, number, number] = [248, 250, 252];    // Slate 50

  let y = 10;

  // Header Banner Accent Line
  doc.setFillColor(...accentColor);
  doc.rect(14, y, pageWidth - 28, 1.5, 'F');
  y += 5;

  // Logo Handling (Dynamic or Default)
  const logoData = companySettings.logoBase64 || LOGO_CORETERRA_BASE64;
  if (logoData) {
    try {
      doc.addImage(logoData, 'PNG', 14, y, 38, 12.58);
    } catch (e) {
      console.error('Failed to render logo:', e);
    }
  }

  const compX = logoData ? 54 : 14;
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  doc.setTextColor(...primaryColor);
  doc.text(companySettings.companyName || 'PT CORETERRA GEO ENGINEERING', compX, y + 3);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(5.8);
  doc.setTextColor(...accentColor);
  doc.text('GEOTECHNICAL • DRILLING • CIVIL ENGINEERING • MINING CONSULTANT', compX, y + 6.5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.2);
  doc.setTextColor(...textColor);
  doc.text(companySettings.address || 'Gardenia Estate, Blok A5 No 12, Ciputat, Tangsel, Banten 15412', compX, y + 10);
  doc.text(`Email: ${companySettings.email || 'admin.cge@coreterra-geo.com'} | Contact: ${companySettings.phone || '+62 812-1494-1641'}`, compX, y + 13.5);

  // Invoice Header Box (Top Right)
  const boxWidth = 60;
  const boxX = pageWidth - 14 - boxWidth;
  
  doc.setFillColor(...lightBg);
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(boxX, y, boxWidth, 19, 2, 2, 'FD');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10.5);
  doc.setTextColor(...primaryColor);
  doc.text('INVOICE / FAKTUR', boxX + 4, y + 4.2);

  const invNum = term.invoice_number || `INV/${term.term_number.toString().padStart(3, '0')}/${schedule.project_code || 'CGE'}/${new Date().toLocaleDateString('en-US', { month: '2-digit' })}/${new Date().getFullYear()}`;

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.5);
  doc.setTextColor(...textColor);
  doc.text('No:', boxX + 4, y + 9.5);
  doc.setFont('helvetica', 'bold');
  doc.text(invNum, boxX + 10, y + 9.5);

  doc.setFont('helvetica', 'normal');
  doc.text('Date / Tgl:', boxX + 4, y + 14.5);
  doc.setFont('helvetica', 'bold');
  doc.text(term.invoice_date || new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }), boxX + 18, y + 14.5);

  y += 23;

  // Thin separator
  doc.setDrawColor(226, 232, 240);
  doc.setLineWidth(0.4);
  doc.line(14, y, pageWidth - 14, y);
  y += 5;

  // 2-Column Section: Bill From & Bill To
  const colWidth = (pageWidth - 34) / 2;

  // Bill From Box
  doc.setFillColor(...lightBg);
  doc.roundedRect(14, y, colWidth, 32, 2, 2, 'F');
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(14, y, colWidth, 32, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.setTextColor(...accentColor);
  doc.text('BILL FROM / DARI:', 18, y + 5.5);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...primaryColor);
  doc.text(companySettings.companyName || 'PT Coreterra Geo Engineering', 18, y + 10.5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text(companySettings.address || 'Gardenia Estate, Blok A5 No 12, Ciputat, Tangsel', 18, y + 15);
  doc.text(`Telp/WA: ${companySettings.phone || '+62 812-1494-1641'}`, 18, y + 19);
  doc.text(`Email: ${companySettings.email || 'admin.cge@coreterra-geo.com'}`, 18, y + 23.5);

  // Bill To Box
  const billToX = 14 + colWidth + 6;
  doc.setFillColor(...lightBg);
  doc.roundedRect(billToX, y, colWidth, 32, 2, 2, 'F');
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(billToX, y, colWidth, 32, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.setTextColor(...accentColor);
  doc.text('BILL TO / KEPADA:', billToX + 4, y + 5.5);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...primaryColor);
  doc.text(schedule.customer_name, billToX + 4, y + 10.5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Attn: Finance / Procurement Department', billToX + 4, y + 15);

  y += 36;

  // Project Reference & Contract Overview Card
  doc.setFillColor(241, 245, 249);
  doc.roundedRect(14, y, pageWidth - 28, 22, 2, 2, 'F');
  doc.setDrawColor(203, 213, 225);
  doc.roundedRect(14, y, pageWidth - 28, 22, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8);
  doc.setTextColor(...primaryColor);
  doc.text('PROJECT & CONTRACT REFERENCE / REFERENSI PROYEK', 18, y + 5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Contract / PO No:', 18, y + 10.5);
  doc.setFont('helvetica', 'bold');
  doc.text(schedule.contract_number || '-', 44, y + 10.5);

  doc.setFont('helvetica', 'normal');
  doc.text('Project Name:', 18, y + 15.5);
  doc.setFont('helvetica', 'bold');
  doc.text(schedule.contract_description || schedule.project_name || 'Project Services', 44, y + 15.5);

  // Total Contract Value Displayed Prominently
  const refValX = pageWidth - 16;
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Nilai Total Kontrak Proyek:', refValX - 48, y + 10.5, { align: 'left' });
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(...accentColor);
  doc.text(formatMoney(schedule.total_contract_value || 2870121121, currency), refValX, y + 16, { align: 'right' });

  y += 26;

  // Invoice Details Table
  const baseAmount = term.amount_before_tax || term.amount || 0;
  const taxAmount = term.tax_amount || 0;
  const totalAmount = term.total_amount || (baseAmount + taxAmount);
  const termUnit = term.unit || 'Lump Sump';

  autoTable(doc, {
    startY: y,
    head: [['No.', 'Item & Payment Terms / Description', 'Milestone', 'Unit', `Amount (${currency})`]],
    body: [
      [
        '1.',
        `${term.term_name}${term.term_name_en ? `\n(${term.term_name_en})` : ''}`,
        term.description || 'Field preparation',
        termUnit,
        formatMoney(baseAmount, currency)
      ]
    ],
    theme: 'grid',
    headStyles: {
      fillColor: primaryColor,
      textColor: [255, 255, 255],
      fontStyle: 'bold',
      fontSize: 8,
      halign: 'center',
      valign: 'middle',
      cellPadding: 3,
    },
    bodyStyles: {
      textColor: [30, 41, 59],
      fontSize: 8,
      valign: 'middle',
      cellPadding: 3.5,
      lineWidth: 0.2,
      lineColor: [226, 232, 240]
    },
    columnStyles: {
      0: { cellWidth: 10, halign: 'center' },
      1: { cellWidth: 55, halign: 'left' },
      2: { cellWidth: 60, halign: 'left' },
      3: { cellWidth: 22, halign: 'center' },
      4: { cellWidth: 'auto', halign: 'right', fontStyle: 'bold' },
    },
    margin: { left: 14, right: 14 },
  });

  // @ts-ignore
  y = doc.lastAutoTable.finalY + 4;

  // Summary & Breakdown Table Box
  const sumWidth = 95;
  const sumX = pageWidth - 14 - sumWidth;

  doc.setFillColor(...lightBg);
  doc.roundedRect(sumX, y, sumWidth, 32, 2, 2, 'FD');
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(sumX, y, sumWidth, 32, 2, 2, 'S');

  const contractVal = schedule.total_contract_value || 2870121121;
  const rpX = sumX + 54;
  const numRightX = sumX + sumWidth - 4;
  const currSym = currency === 'USD' ? '$' : 'Rp';

  let sy = y + 4.5;
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(...textColor);
  doc.text('Nilai Total Kontrak Proyek:', sumX + 4, sy);
  doc.text(currSym, rpX, sy);
  doc.setFont('helvetica', 'bold');
  doc.text(`${contractVal.toLocaleString(currency === 'USD' ? 'en-US' : 'id-ID')},-`, numRightX, sy, { align: 'right' });

  sy += 4.5;
  doc.setFont('helvetica', 'normal');
  doc.text('Tagihan Ini (Subtotal):', sumX + 4, sy);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(...primaryColor);
  doc.text(currSym, rpX, sy);
  doc.text(`${baseAmount.toLocaleString(currency === 'USD' ? 'en-US' : 'id-ID')},-`, numRightX, sy, { align: 'right' });

  sy += 4.5;
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(...textColor);
  doc.text(`PPN (${schedule.ppn_rate || 11}%) / Tax:`, sumX + 4, sy);
  doc.text(currSym, rpX, sy);
  doc.text(taxAmount > 0 ? `${taxAmount.toLocaleString(currency === 'USD' ? 'en-US' : 'id-ID')},-` : '0,- (Included)', numRightX, sy, { align: 'right' });

  sy += 5.5;
  doc.setDrawColor(203, 213, 225);
  doc.line(sumX + 4, sy - 2, sumX + sumWidth - 4, sy - 2);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8.5);
  doc.setTextColor(...accentColor);
  doc.text('Total Harus Dibayar / Due:', sumX + 4, sy + 1.5);
  doc.text(currSym, rpX, sy + 1.5);
  doc.text(`${totalAmount.toLocaleString(currency === 'USD' ? 'en-US' : 'id-ID')},-`, numRightX, sy + 1.5, { align: 'right' });

  // Left Note Box: Contract Breakdown
  const remainingVal = Math.max(0, contractVal - totalAmount);
  const noteWidth = pageWidth - 28 - sumWidth - 5;

  doc.setFillColor(254, 243, 199);
  doc.roundedRect(14, y, noteWidth, 32, 2, 2, 'F');
  doc.setDrawColor(252, 211, 77);
  doc.roundedRect(14, y, noteWidth, 32, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(146, 64, 14);
  doc.text('INFORMASI STRUKTUR KONTRAK', 18, y + 4.5);

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6.8);
  doc.setTextColor(120, 53, 15);
  doc.text(`• Persentase Tagihan Ini: ${term.percentage || 0}% dari Kontrak`, 18, y + 9.5);
  doc.text(`• Sisa Nilai Kontrak: ${formatMoney(remainingVal, currency)}`, 18, y + 14);
  doc.text('• Tempo Pembayaran: 7 Hari setelah invoice diterima', 18, y + 18.5);

  y += 36;

  // Bank Account Details Box
  doc.setFillColor(...lightBg);
  doc.roundedRect(14, y, pageWidth - 28, 25, 2, 2, 'FD');
  doc.setDrawColor(226, 232, 240);
  doc.roundedRect(14, y, pageWidth - 28, 25, 2, 2, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(8);
  doc.setTextColor(...accentColor);
  doc.text('REKENING PEMBAYARAN / BANK DETAILS FOR PAYMENT:', 18, y + 4.5);

  const bankInfo = [
    ['Nama Bank / Bank Name', `: ${schedule.bank_name || 'Bank Mandiri'}`],
    ['Atas Nama / Account Name', `: ${schedule.bank_account_name || companySettings.companyName || 'PT Coreterra Geo Engineering'}`],
    ['Nomor Rekening / Account No.', `: ${schedule.bank_account_number || '103-00-1332575-4'}`],
    ['Kode SWIFT / IFSC Code', ': BMRIIDJA'],
    ['Cabang / Branch Name', ': KCP Jakarta Gedung Jaya'],
    ['NPWP / TIN', `: ${companySettings.taxId || '1000 0000 1002 1192'}`],
  ];

  let by1 = y + 9.5;
  let by2 = y + 9.5;
  bankInfo.forEach(([lbl, val], idx) => {
    doc.setFontSize(7.5);
    if (idx < 3) {
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(...textColor);
      doc.text(lbl, 18, by1);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(...primaryColor);
      doc.text(val, 58, by1);
      by1 += 4.5;
    } else {
      const bx = 110;
      doc.setFont('helvetica', 'normal');
      doc.setTextColor(...textColor);
      doc.text(lbl, bx, by2);
      doc.setFont('helvetica', 'bold');
      doc.setTextColor(...primaryColor);
      doc.text(val, bx + 44, by2);
      by2 += 4.5;
    }
  });

  y += 28;

  // Signature Block & Stamp (Right aligned)
  const sigX = pageWidth - 65;
  renderSignatureBlock(doc, sigX, y, companySettings.companyName || 'PT Coreterra Geo Engineering');

  // Render Beautiful Footer
  drawBeautifulFooter(doc, companySettings.companyName || 'PT CORETERRA GEO ENGINEERING');

  openPdfInNewTab(doc, invNum);
}
